// ============ 二叉树结点长什么样 ============
//
//           data
//          ┌────┐
//          │ A  │
//          └─┬──┘
//        left │ right
//         ┌───┴───┐
//        ▼       ▼
//      ┌────┐  ┌────┐
//      │ B  │  │ C  │
//      └────┘  └────┘
//
// 每个结点除了存数据，还要存**两个孩子在哪**。
// 没有孩子就是 NULL —— 所以"空指针"在树里是个正常状态，到处都是。
//
// ============ 和链表的区别 ============
//
//   链表结点：一个 next，一条链走到底          → 线性
//   树结点  ：一个 left、一个 right，两个岔路   → 层次
//
// 多出来的这个指针，正是"树"能表达层次关系的原因。

// 数据元素类型：换成 int 也只要改这一行
typedef char ElemType;

// 二叉树结点
typedef struct TNode
{
// 数据域
    ElemType data;
// 左孩子
    struct TNode *left;
// 右孩子
    struct TNode *right;
} TNode, *BinTree;

// 状态码（沿用前面的约定）
#define OK 1
#define ERROR 0
typedef int Status;

