/* ======== 测试驱动（已给出，可自行修改） ======== */
/* 验证结构定义：一个结点有两个孩子指针 */
int main(void)
{
    TNode n;

    n.data = 'A';
    n.left = NULL;
    n.right = NULL;

    printf("sizeof(TNode) = %d 字节\n", (int)sizeof(TNode));
    printf("sizeof(BinTree) = %d 字节（就是指针大小）\n", (int)sizeof(BinTree));
    printf("结点 %c 的 left 是 %s，right 是 %s\n", n.data,
           n.left == NULL ? "空" : "非空", n.right == NULL ? "空" : "非空");
    printf("（树里 NULL 表示「没有孩子」，是正常状态）\n");

    return 0;
}

modes.detail:
// ============ 和链表的 creatNode 一模一样 ============
//
// 区别只有一点：链表要置一个 next，树要置**两个**指针（left 和 right）。
// 少置一个就是野指针，遍历时随机崩溃 —— 而且往往不在出错的那一行崩，
// 找起来很痛苦。
//
// 所以这里用 malloc 之后立刻把两个指针都写上 NULL，不给野指针留机会。
// （用 calloc 也可以，它会自动清零，但显式写出来意图更清楚。）

// 造一个值为 e 的孤立结点
BinTree NewNode(ElemType e)
{
// 申请一块 TNode 大小的内存
    BinTree t = (BinTree)malloc(sizeof(TNode));
// 满内存要挡住
    if (t == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }
// 填数据
    t->data = e;
// 两个孩子都置空 —— 树里 NULL 表示"没有孩子"
    t->left = NULL;
    t->right = NULL;
// 返回
    return t;
}

