int main(void)
{
    const char *s = "ABD##E##C#F##";
    int i = 0;
    BinTree root = CreateTree(s, &i);

    printf("输入序列: %s\n", s);
    printf("读取字符: %d 个\n", i);
    printf("根结点  : %c\n", root->data);
    printf("左孩子  : %c\n", root->left->data);
    printf("右孩子  : %c\n", root->right->data);
    printf("先序打回来: ");
    PreOrder(root);
    printf("\n（应该和输入序列去掉所有 # 之后一致：ABDECF）\n");

    FreeTree(root);
