}

modes.detail:
// ============ 递归三行就够 ============
//
//   先序：打印自己 → 递归左 → 递归右
//
// 走一遍这棵树：
//
//           A
//         /   \
//        B     C
//       / \     \
//      D   E     F
//
//   访问 A → 进左子树：访问 B → 进左子树：访问 D → D 无孩子，回退
//            → 进 B 的右子树：访问 E → E 无孩子，回退
//        → 进右子树：访问 C → C 没有左孩子 → 进右子树：访问 F
//
//   结果：A B D E C F
//
// ============ 递归为什么能"回退" ============
//
// 函数调用栈帮你记着"我走到哪儿了"。访问完 D 返回时，程序自动回到
// "B 的左子树刚处理完"这个位置，接着去处理 B 的右子树。
//
// 递归的写法之所以短，就是把这份"记账"交给了调用栈。

// 先序遍历并打印
void PreOrder(BinTree T)
{
// 空树是递归的出口
// 树的每个操作几乎都以这一句开头。漏了它，遇到空结点解引用就会崩。
    if (T == NULL)
    {
        return;
    }

// 先处理根（先序的关键就在这一句的位置）
    printf("%c ", T->data);

// 再递归左子树
    PreOrder(T->left);

// 最后递归右子树
    PreOrder(T->right);
}

