// ============ 递归做不了层序 ============
//
// 前三种遍历都是"一路往下钻"，递归天然合适。
// 层序要求**横向**推进：先访问第 1 层所有结点，再第 2 层……
// 递归的调用栈是纵向的，帮不上忙，得另外借一个**队列**。
//
// 做法：
//
//   ① 根入队
//   ② 循环：出队一个 → 打印它 → 把它的左右孩子依次入队
//   ③ 队空就结束
//
// 走一遍：
//
//   队列 [A]        → 出 A，打印 A，入 B、C          队列 [B C]
//   队列 [B C]      → 出 B，打印 B，入 D、E          队列 [C D E]
//   队列 [C D E]    → 出 C，打印 C，入 F（没有左孩子）队列 [D E F]
//   ... → 结果：A B C D E F
//
// 关键点：**入队顺序决定了下一层的访问顺序**，所以先左后右不能反。
//
// 这里为了不依赖 02-04 的队列代码，用一个数组加两个下标直接当队列用。

// 层序遍历并打印
void LevelOrder(BinTree T)
{
// 自己搭一个简单队列：定长数组 + 头尾下标
// 树最多几十个结点，开 64 个位置绰绰有余。
    BinTree q[64];
// 队头下标（出队处）
    int front = 0;
// 队尾下标（入队处）
    int rear = 0;

// 空树直接返回
    if (T == NULL)
    {
        return;
    }

// ① 根入队
    q[rear++] = T;

// ② 队列不空就一直转
    while (front < rear)
    {
// 出队一个并打印
        BinTree cur = q[front++];
        printf("%c ", cur->data);

// ③ 左孩子入队 —— 必须先左后右，否则同一层的顺序会颠倒
        if (cur->left != NULL)
        {
            q[rear++] = cur->left;
        }
// 右孩子入队
        if (cur->right != NULL)
        {
            q[rear++] = cur->right;
        }
    }
}

