modes.detail:
// ============ 一眼看清四种遍历的差别 ============
//
// 用的是同一棵树：
//
//           A
//         /   \
//        B     C
//       / \     \
//      D   E     F
//
// 先序  A B D E C F      （根最先）
// 中序  D B E A C F      （根居中）
// 后序  D E B F C A      （根最后）
// 层序  A B C D E F      （一层一层）
//
// 前三个只差 printf 的位置，序列却完全不同 —— 这就是递归顺序的威力。

// 主函数
int main(void)
{
// 先序序列：# 表示空孩子
    const char *s = "ABD##E##C#F##";
// 读序列用的游标
    int i = 0;
// 树根
    BinTree root;

// 打印建树用的序列，方便对照
    printf("建树序列(先序, #=空): %s\n\n", s);

// 建树
    root = CreateTree(s, &i);
    printf("建树完成，共读取 %d 个字符\n\n", i);

// 四种遍历各来一遍
    printf("先序 (根 左 右): ");
    PreOrder(root);
    printf("\n");

    printf("中序 (左 根 右): ");
    InOrder(root);
    printf("\n");

    printf("后序 (左 右 根): ");
    PostOrder(root);
    printf("\n");

    printf("层序 (一层一层): ");
    LevelOrder(root);
    printf("\n");

// 释放
// 每个 malloc 都要有对应的 free —— 树也一样，只是顺序必须是后序。
    FreeTree(root);
    printf("\n整棵树已释放（后序：先孩子后自己）\n");

// 正常结束
    return 0;
}

