#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// ============ 二叉树结点长什么样 ============
//
//           data
//          ┌────┐
//          │ A  │
//          └─┬──┘
//        left │ right
//         ┌───┴───┐
//        ▼       ▼
//      ┌────┐  ┌────┐
//      │ B  │  │ C  │
//      └────┘  └────┘
//
// 每个结点除了存数据，还要存**两个孩子在哪**。
// 没有孩子就是 NULL —— 所以"空指针"在树里是个正常状态，到处都是。
//
// ============ 和链表的区别 ============
//
//   链表结点：一个 next，一条链走到底          → 线性
//   树结点  ：一个 left、一个 right，两个岔路   → 层次
//
// 多出来的这个指针，正是"树"能表达层次关系的原因。

// 数据元素类型：换成 int 也只要改这一行
typedef char ElemType;

// 二叉树结点
typedef struct TNode
{
// 数据域
    ElemType data;
// 左孩子
    struct TNode *left;
// 右孩子
    struct TNode *right;
} TNode, *BinTree;

// 状态码（沿用前面的约定）
#define OK 1
#define ERROR 0
typedef int Status;

// ============ 和链表的 creatNode 一模一样 ============
//
// 区别只有一点：链表要置一个 next，树要置**两个**指针（left 和 right）。
// 少置一个就是野指针，遍历时随机崩溃 —— 而且往往不在出错的那一行崩，
// 找起来很痛苦。
//
// 所以这里用 malloc 之后立刻把两个指针都写上 NULL，不给野指针留机会。
// （用 calloc 也可以，它会自动清零，但显式写出来意图更清楚。）

// 造一个值为 e 的孤立结点
BinTree NewNode(ElemType e)
{
// 申请一块 TNode 大小的内存
    BinTree t = (BinTree)malloc(sizeof(TNode));
// 满内存要挡住
    if (t == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }
// 填数据
    t->data = e;
// 两个孩子都置空 —— 树里 NULL 表示"没有孩子"
    t->left = NULL;
    t->right = NULL;
// 返回
    return t;
}

// ============ 用一段字符描述一棵树 ============
//
// 直接写代码一棵一棵拼结点太啰嗦，所以约定一种**先序序列**：
//
//   先输出根，再递归输出左子树，再递归输出右子树；
//   遇到空孩子就输出一个 '#'。
//
// 比如这棵树：
//
//           A
//         /   \
//        B     C
//       / \     \
//      D   E     F
//
// 它的先序序列就是：**A B D # # E # # C # F # #**
//
// 读法：A 是根；接着 B 是 A 的左孩子；D 是 B 的左孩子；
// 两个 # 说明 D 没有孩子；回到 B，E 是它的右孩子…… 一路递归下去。
//
// ============ 为什么用先序 ============
//
// 因为**先序序列的第一个一定是根**，读完根立刻知道接下来要去建左子树。
// 换成中序或后序就没法这样一边读一边建（得先把整串读完才能定位根）。
//
// 这也是"先序遍历可以用来序列化一棵树"的原因。

// i 是当前读到序列的哪一位 —— 必须传指针，因为递归时要"共享进度"
// 如果按值传 i，每个递归层都有自己的 i，整串就被重复读了。
BinTree CreateTree(const char *s, int *i)
{
// 取出当前字符并把游标往后挪
    char c = s[(*i)++];

// '#' 表示这里没有结点（空孩子），直接返回 NULL
    if (c == '#' || c == '\0')
    {
        return NULL;
    }

// 建根结点
    BinTree t = NewNode(c);

// 递归建左子树 —— 紧接着的那些字符就是左子树的先序序列
    t->left = CreateTree(s, i);

// 再递归建右子树
// 这一步看起来"什么都没做"，其实全靠 (*i) 在递归过程中被一路推进 ——
// 左子树消费掉多少个字符，右子树就从下一个位置接着读。
    t->right = CreateTree(s, i);

// 返回这棵子树
    return t;
}

// ============ 递归三行就够 ============
//
//   先序：打印自己 → 递归左 → 递归右
//
// 走一遍这棵树：
//
//           A
//         /   \
//        B     C
//       / \     \
//      D   E     F
//
//   访问 A → 进左子树：访问 B → 进左子树：访问 D → D 无孩子，回退
//            → 进 B 的右子树：访问 E → E 无孩子，回退
//        → 进右子树：访问 C → C 没有左孩子 → 进右子树：访问 F
//
//   结果：A B D E C F
//
// ============ 递归为什么能"回退" ============
//
// 函数调用栈帮你记着"我走到哪儿了"。访问完 D 返回时，程序自动回到
// "B 的左子树刚处理完"这个位置，接着去处理 B 的右子树。
//
// 递归的写法之所以短，就是把这份"记账"交给了调用栈。

// 先序遍历并打印
void PreOrder(BinTree T)
{
// 空树是递归的出口
// 树的每个操作几乎都以这一句开头。漏了它，遇到空结点解引用就会崩。
    if (T == NULL)
    {
        return;
    }

// 先处理根（先序的关键就在这一句的位置）
    printf("%c ", T->data);

// 再递归左子树
    PreOrder(T->left);

// 最后递归右子树
    PreOrder(T->right);
}

// ============ 只把打印挪了个位置 ============
//
// 和先序相比，代码几乎一样，只是 printf 从"最前面"挪到了"中间"：
//
//   先序：printf → 递归左 → 递归右
//   中序：递归左 → printf → 递归右
//
// 就这一挪，输出的含义完全不同。还是那棵树：
//
//           A
//         /   \
//        B     C
//       / \     \
//      D   E     F
//
//   先走完左边：D、B、E（注意 B 夹在中间）→ 再 A → 再右边：C、F
//   结果：D B E A C F
//
// ============ 中序的地位 ============
//
// 中序遍历有一个别的遍历都没有的性质：
// **对二叉搜索树做中序遍历，结果一定是递增有序的。**
//
// 所以在接下来 BST 那一节里，验证一棵树对不对，最省事的办法就是中序打一遍。
// 反过来，如果题目给的序列是有序的，那多半是在提示你"用中序"。

// 中序遍历并打印
void InOrder(BinTree T)
{
// 空树返回
    if (T == NULL)
    {
        return;
    }

// 先递归左子树 —— 先把左边走到底
    InOrder(T->left);

// 再打印自己（中序的关键位置）
    printf("%c ", T->data);

// 最后递归右子树
    InOrder(T->right);
}

// ============ 后序的独特价值 ============
//
//   后序：递归左 → 递归右 → printf
//
// 还是那棵树，输出是：D E B F C A（根 A 跑到最后）
//
// 为什么"根在最后"很有用？因为凡是**必须等孩子处理完才能处理自己**
// 的事情，都得用后序：
//
//   ① 释放整棵树 —— 你要是先 free 了根，就再也找不到孩子了
//   ② 计算表达式树 —— 得先算出左右子树的值，才能算运算符
//   ③ 统计树的高度 —— 得先知道左右子树多高
//
// 这三个操作在写法上有共同点：都是**先递归，拿到返回值，再处理自己**。
// 下面的 main 里会用到第 ① 个。

// 后序遍历并打印
void PostOrder(BinTree T)
{
// 空树返回
    if (T == NULL)
    {
        return;
    }

// 先递归左子树
    PostOrder(T->left);

// 再递归右子树
    PostOrder(T->right);

// 最后才打印自己（后序的关键位置）
    printf("%c ", T->data);
}

// ============ 递归做不了层序 ============
//
// 前三种遍历都是"一路往下钻"，递归天然合适。
// 层序要求**横向**推进：先访问第 1 层所有结点，再第 2 层……
// 递归的调用栈是纵向的，帮不上忙，得另外借一个**队列**。
//
// 做法：
//
//   ① 根入队
//   ② 循环：出队一个 → 打印它 → 把它的左右孩子依次入队
//   ③ 队空就结束
//
// 走一遍：
//
//   队列 [A]        → 出 A，打印 A，入 B、C          队列 [B C]
//   队列 [B C]      → 出 B，打印 B，入 D、E          队列 [C D E]
//   队列 [C D E]    → 出 C，打印 C，入 F（没有左孩子）队列 [D E F]
//   ... → 结果：A B C D E F
//
// 关键点：**入队顺序决定了下一层的访问顺序**，所以先左后右不能反。
//
// 这里为了不依赖 02-04 的队列代码，用一个数组加两个下标直接当队列用。

// 层序遍历并打印
void LevelOrder(BinTree T)
{
// 自己搭一个简单队列：定长数组 + 头尾下标
// 树最多几十个结点，开 64 个位置绰绰有余。
    BinTree q[64];
// 队头下标（出队处）
    int front = 0;
// 队尾下标（入队处）
    int rear = 0;

// 空树直接返回
    if (T == NULL)
    {
        return;
    }

// ① 根入队
    q[rear++] = T;

// ② 队列不空就一直转
    while (front < rear)
    {
// 出队一个并打印
        BinTree cur = q[front++];
        printf("%c ", cur->data);

// ③ 左孩子入队 —— 必须先左后右，否则同一层的顺序会颠倒
        if (cur->left != NULL)
        {
            q[rear++] = cur->left;
        }
// 右孩子入队
        if (cur->right != NULL)
        {
            q[rear++] = cur->right;
        }
    }
}

// ============ 为什么必须是后序 ============
//
// 释放一棵树，直觉上会想"从根开始 free"。但 free 掉根之后，
// 你就**再也找不到它的孩子了** —— 那些结点谁也没记着地址，永远收不回来。
//
// 所以正确顺序只有一个：**先把左右子树都释放干净，最后才 free 自己**。
// 这恰好就是后序遍历的顺序。
//
// 凡是"必须等孩子处理完才能处理自己"的操作，都得用后序 ——
// 释放内存、算表达式树、求树高，都是这一类。

// 先释放根就找不到孩子了，所以一定是"先孩子、后自己"。
void FreeTree(BinTree T)
{
// 空树返回
    if (T == NULL)
    {
        return;
    }
// 先把左子树整个释放掉
    FreeTree(T->left);
// 再释放右子树
    FreeTree(T->right);
// 最后才释放自己
    free(T);
}

// ============ 一眼看清四种遍历的差别 ============
//
// 用的是同一棵树：
//
//           A
//         /   \
//        B     C
//       / \     \
//      D   E     F
//
// 先序  A B D E C F      （根最先）
// 中序  D B E A C F      （根居中）
// 后序  D E B F C A      （根最后）
// 层序  A B C D E F      （一层一层）
//
// 前三个只差 printf 的位置，序列却完全不同 —— 这就是递归顺序的威力。

// 主函数
int main(void)
{
// 先序序列：# 表示空孩子
    const char *s = "ABD##E##C#F##";
// 读序列用的游标
    int i = 0;
// 树根
    BinTree root;

// 打印建树用的序列，方便对照
    printf("建树序列(先序, #=空): %s\n\n", s);

// 建树
    root = CreateTree(s, &i);
    printf("建树完成，共读取 %d 个字符\n\n", i);

// 四种遍历各来一遍
    printf("先序 (根 左 右): ");
    PreOrder(root);
    printf("\n");

    printf("中序 (左 根 右): ");
    InOrder(root);
    printf("\n");

    printf("后序 (左 右 根): ");
    PostOrder(root);
    printf("\n");

    printf("层序 (一层一层): ");
    LevelOrder(root);
    printf("\n");

// 释放
// 每个 malloc 都要有对应的 free —— 树也一样，只是顺序必须是后序。
    FreeTree(root);
    printf("\n整棵树已释放（后序：先孩子后自己）\n");

// 正常结束
    return 0;
}

