#include <stdio.h>
#include <stdlib.h>
#include <string.h>


// 数据元素类型：换成 int 也只要改这一行
typedef char ElemType;

// 二叉树结点
typedef struct TNode
{
// 数据域
    ElemType data;
// 左孩子
    struct TNode *left;
// 右孩子
    struct TNode *right;
} TNode, *BinTree;

// 状态码（沿用前面的约定）
#define OK 1
#define ERROR 0
typedef int Status;


// 造一个值为 e 的孤立结点
BinTree NewNode(ElemType e)
{
// 申请一块 TNode 大小的内存
    BinTree t = (BinTree)malloc(sizeof(TNode));
// 满内存要挡住
    if (t == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }
// 填数据
    t->data = e;
// 两个孩子都置空 —— 树里 NULL 表示"没有孩子"
    t->left = NULL;
    t->right = NULL;
// 返回
    return t;
}


// i 是当前读到序列的哪一位 —— 必须传指针，因为递归时要"共享进度"
BinTree CreateTree(const char *s, int *i)
{
// 取出当前字符并把游标往后挪
    char c = s[(*i)++];

// '#' 表示这里没有结点（空孩子），直接返回 NULL
    if (c == '#' || c == '\0')
    {
        return NULL;
    }

// 建根结点
    BinTree t = NewNode(c);

// 递归建左子树 —— 紧接着的那些字符就是左子树的先序序列
    t->left = CreateTree(s, i);

// 再递归建右子树
    t->right = CreateTree(s, i);

// 返回这棵子树
    return t;
}


// 先序遍历并打印
void PreOrder(BinTree T)
{
// 空树是递归的出口
    if (T == NULL)
    {
        return;
    }

// 先处理根（先序的关键就在这一句的位置）
    printf("%c ", T->data);

