    if (T == NULL)
    {
        return;
    }

// 先递归左子树 —— 先把左边走到底
    InOrder(T->left);

// 再打印自己（中序的关键位置）
    printf("%c ", T->data);

// 最后递归右子树
    InOrder(T->right);
}


// 后序遍历并打印
void PostOrder(BinTree T)
{
// 空树返回
    if (T == NULL)
    {
        return;
    }

// 先递归左子树
    PostOrder(T->left);

// 再递归右子树
    PostOrder(T->right);

// 最后才打印自己（后序的关键位置）
    printf("%c ", T->data);
}


// 层序遍历并打印
void LevelOrder(BinTree T)
{
// 自己搭一个简单队列：定长数组 + 头尾下标
    BinTree q[64];
// 队头下标（出队处）
    int front = 0;
