        BinTree cur = q[front++];
        printf("%c ", cur->data);

// ③ 左孩子入队 —— 必须先左后右，否则同一层的顺序会颠倒
        if (cur->left != NULL)
        {
            q[rear++] = cur->left;
        }
// 右孩子入队
        if (cur->right != NULL)
        {
            q[rear++] = cur->right;
        }
    }
